"""确定性图形脚本生成（Mermaid / Graphviz / TikZ / Matplotlib）。

本模块只生成脚本文本，不调用 graphviz、pdflatex 或 matplotlib：

* 同一 ``spec`` 的脚本严格字节一致（不使用时间戳、随机 id、集合遍历）；
* 布局由纯 Python 的拓扑分层算法给出，坐标保留固定精度；
* 脚本交给调用方在自己的环境中渲染，便于评审复现。
"""

from __future__ import annotations

import re
from typing import Any

from ..core.errors import ValidationError
from ..core.hashing import short_id

SUPPORTED_KINDS: tuple[str, ...] = ("tikz", "graphviz", "mermaid", "matplotlib")

_EXTENSIONS = {"tikz": "tex", "graphviz": "dot", "mermaid": "mmd", "matplotlib": "py"}
_HEADERS = {
    "tikz": "% generated by academic writing copilot (deterministic tikz source)",
    "graphviz": "// generated by academic writing copilot (deterministic graphviz source)",
    "mermaid": "%% generated by academic writing copilot (deterministic mermaid source)",
    "matplotlib": "# generated by academic writing copilot (deterministic matplotlib source)",
}
_KIND_ALIASES = {"dot": "graphviz", "gv": "graphviz", "tex": "tikz", "mmd": "mermaid", "py": "matplotlib"}


def _tikz_escape(text: str) -> str:
    return (
        str(text)
        .replace("\\", r"\textbackslash{}")
        .replace("&", r"\&")
        .replace("%", r"\%")
        .replace("$", r"\$")
        .replace("#", r"\#")
        .replace("_", r"\_")
        .replace("{", r"\{")
        .replace("}", r"\}")
        .replace("~", r"\textasciitilde{}")
        .replace("^", r"\textasciicircum{}")
    )


def _dot_escape(text: str) -> str:
    return str(text).replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")


def _mm_escape(text: str) -> str:
    return str(text).replace("\n", " ").replace('"', "#quot;").replace("`", "#96;")


def _safe_names(nodes: list[dict[str, Any]]) -> dict[str, str]:
    """把任意节点 id 映射成 ASCII 标识符（tikz / mermaid 需要）。"""
    mapping: dict[str, str] = {}
    used: set[str] = set()
    for node in nodes:
        base = re.sub(r"[^0-9A-Za-z]+", "_", node["id"]).strip("_") or "n"
        if base[0].isdigit():
            base = f"n_{base}"
        name = base
        suffix = 2
        while name in used:
            name = f"{base}_{suffix}"
            suffix += 1
        used.add(name)
        mapping[node["id"]] = name
    return mapping


def _normalize_spec(spec: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(spec, dict):
        raise ValidationError("spec 必须是 JSON 对象")
    raw_nodes = spec.get("nodes") or []
    if not isinstance(raw_nodes, (list, tuple)):
        raise ValidationError("spec.nodes 必须是数组")
    nodes: list[dict[str, str]] = []
    seen: set[str] = set()
    for index, item in enumerate(raw_nodes):
        if not isinstance(item, dict):
            raise ValidationError(f"nodes[{index}] 必须是对象")
        node_id = str(item.get("id") or "").strip()
        if not node_id:
            raise ValidationError(f"nodes[{index}] 缺少 id")
        if node_id in seen:
            raise ValidationError(f"节点 id 重复: {node_id}")
        seen.add(node_id)
        label = str(item.get("label") or node_id).strip() or node_id
        group = str(item.get("group") or "").strip()
        nodes.append({"id": node_id, "label": label, "group": group})

    raw_edges = spec.get("edges") or []
    if not isinstance(raw_edges, (list, tuple)):
        raise ValidationError("spec.edges 必须是数组")
    edges: list[dict[str, str]] = []
    for index, item in enumerate(raw_edges):
        if not isinstance(item, dict):
            raise ValidationError(f"edges[{index}] 必须是对象")
        source = str(item.get("source") or "").strip()
        target = str(item.get("target") or "").strip()
        if not source or not target:
            raise ValidationError(f"edges[{index}] 缺少 source/target")
        if source not in seen:
            raise ValidationError(f"edges[{index}].source 指向不存在的节点: {source}")
        if target not in seen:
            raise ValidationError(f"edges[{index}].target 指向不存在的节点: {target}")
        edges.append(
            {
                "source": source,
                "target": target,
                "label": str(item.get("label") or "").strip(),
                "style": str(item.get("style") or "").strip().lower(),
            }
        )

    raw_clusters = spec.get("clusters") or []
    if not isinstance(raw_clusters, (list, tuple)):
        raise ValidationError("spec.clusters 必须是数组")
    clusters: list[dict[str, Any]] = []
    cluster_ids: set[str] = set()
    assigned: set[str] = set()
    for index, item in enumerate(raw_clusters):
        if not isinstance(item, dict):
            raise ValidationError(f"clusters[{index}] 必须是对象")
        cluster_id = str(item.get("id") or f"c{index + 1}").strip() or f"c{index + 1}"
        if cluster_id in cluster_ids:
            raise ValidationError(f"cluster id 重复: {cluster_id}")
        cluster_ids.add(cluster_id)
        members: list[str] = []
        for raw in item.get("nodes") or []:
            member = str(raw or "").strip()
            if not member:
                continue
            if member not in seen:
                raise ValidationError(f"clusters[{index}] 引用了不存在的节点: {member}")
            if member in assigned:
                raise ValidationError(f"节点 {member} 同时属于多个 cluster")
            assigned.add(member)
            members.append(member)
        label = str(item.get("label") or cluster_id).strip() or cluster_id
        clusters.append({"id": cluster_id, "label": label, "nodes": members})

    if not clusters:
        # 没有显式 clusters 时按 group 自动分组（保持节点出现顺序）
        order: list[str] = []
        grouped: dict[str, list[str]] = {}
        for node in nodes:
            group = node["group"]
            if not group:
                continue
            if group not in grouped:
                grouped[group] = []
                order.append(group)
            grouped[group].append(node["id"])
        for index, group in enumerate(order):
            clusters.append({"id": f"g{index + 1}", "label": group, "nodes": grouped[group]})

    return {
        "nodes": nodes,
        "edges": edges,
        "clusters": clusters,
        "title": str(spec.get("title") or "").strip(),
        "node_map": {node["id"]: node for node in nodes},
    }


def _layered_layout(
    nodes: list[dict[str, Any]],
    edges: list[dict[str, Any]],
) -> dict[str, dict[str, float]]:
    """Kahn 拓扑分层 + 固定网格坐标；有环时把环上节点追加到最后一层。"""
    order = [node["id"] for node in nodes]
    index = {node_id: position for position, node_id in enumerate(order)}
    incoming = {node_id: 0 for node_id in order}
    outgoing: dict[str, list[str]] = {node_id: [] for node_id in order}
    for edge in edges:
        outgoing[edge["source"]].append(edge["target"])
        incoming[edge["target"]] += 1

    levels = {node_id: 0 for node_id in order}
    remaining = dict(incoming)
    queue = [node_id for node_id in order if remaining[node_id] == 0]
    processed = 0
    while queue:
        queue.sort(key=lambda item: index[item])
        node_id = queue.pop(0)
        processed += 1
        for target in outgoing[node_id]:
            levels[target] = max(levels[target], levels[node_id] + 1)
            remaining[target] -= 1
            if remaining[target] == 0:
                queue.append(target)

    if processed < len(order):
        cycle = [node_id for node_id in order if remaining[node_id] > 0]
        bump = max(levels.values(), default=0) + 1
        for position, node_id in enumerate(cycle):
            levels[node_id] = bump + position

    by_level: dict[int, list[str]] = {}
    for node_id in order:
        by_level.setdefault(levels[node_id], []).append(node_id)
    positions: dict[str, dict[str, float]] = {}
    for level in sorted(by_level):
        for row, node_id in enumerate(by_level[level]):
            positions[node_id] = {"x": level * 3.2, "y": -row * 1.6}
    return positions


def _mm_arrow(style: str) -> str:
    return {"dashed": "-.->", "bold": "==>", "invisible": "~~~"}.get(style, "-->")


def _build_mermaid(graph: dict[str, Any], layout: dict[str, dict[str, float]]) -> str:
    nodes = graph["nodes"]
    edges = graph["edges"]
    clusters = graph["clusters"]
    node_map = graph["node_map"]
    names = _safe_names(nodes)
    lines = [_HEADERS["mermaid"], "flowchart TD"]
    if graph["title"]:
        lines.append(f"  %% {_mm_escape(graph['title'])}")
    in_cluster: set[str] = set()
    for index, cluster in enumerate(clusters):
        lines.append(f'  subgraph c{index + 1}["{_mm_escape(cluster["label"])}"]')
        for node_id in cluster["nodes"]:
            lines.append(f'    {names[node_id]}["{_mm_escape(node_map[node_id]["label"])}"]')
            in_cluster.add(node_id)
        lines.append("  end")
    for node in nodes:
        if node["id"] not in in_cluster:
            lines.append(f'  {names[node["id"]]}["{_mm_escape(node["label"])}"]')
    for edge in edges:
        arrow = _mm_arrow(edge["style"])
        source, target = names[edge["source"]], names[edge["target"]]
        if edge["label"] and edge["style"] != "invisible":
            lines.append(f'  {source} {arrow}|"{_mm_escape(edge["label"])}"| {target}')
        else:
            lines.append(f"  {source} {arrow} {target}")
    return "\n".join(lines).rstrip() + "\n"


def _build_graphviz(graph: dict[str, Any], layout: dict[str, dict[str, float]]) -> str:
    nodes = graph["nodes"]
    edges = graph["edges"]
    clusters = graph["clusters"]
    node_map = graph["node_map"]
    title = _dot_escape(graph["title"] or "diagram")
    lines = [
        _HEADERS["graphviz"],
        f'digraph "{title}" {{',
        "  graph [rankdir=LR, splines=ortho, fontsize=11];",
        '  node [shape=box, style="rounded,filled", fillcolor=white, fontsize=11];',
        "  edge [fontsize=9];",
    ]
    cluster_of: dict[str, str] = {}
    for index, cluster in enumerate(clusters):
        cluster_name = f"cluster_{index + 1}"
        lines.extend(
            [
                f'  subgraph "{cluster_name}" {{',
                f'    label="{_dot_escape(cluster["label"])}";',
                '    style="rounded,dashed";',
            ]
        )
        for node_id in cluster["nodes"]:
            cluster_of[node_id] = cluster_name
            lines.append(
                f'    "{_dot_escape(node_id)}" [label="{_dot_escape(node_map[node_id]["label"])}"];'
            )
        lines.append("  }")
    for node in nodes:
        if node["id"] not in cluster_of:
            lines.append(f'  "{_dot_escape(node["id"])}" [label="{_dot_escape(node["label"])}"];')
    for edge in edges:
        attrs = []
        if edge["label"]:
            attrs.append(f'label="{_dot_escape(edge["label"])}"')
        if edge["style"] == "dashed":
            attrs.append("style=dashed")
        elif edge["style"] == "bold":
            attrs.append("penwidth=1.8")
        elif edge["style"] == "invisible":
            attrs.append("style=invis")
        suffix = f" [{', '.join(attrs)}]" if attrs else ""
        lines.append(
            f'  "{_dot_escape(edge["source"])}" -> "{_dot_escape(edge["target"])}"{suffix};'
        )
    lines.append("}")
    return "\n".join(lines).rstrip() + "\n"


def _build_tikz(graph: dict[str, Any], layout: dict[str, dict[str, float]]) -> str:
    nodes = graph["nodes"]
    edges = graph["edges"]
    clusters = graph["clusters"]
    node_map = graph["node_map"]
    names = _safe_names(nodes)
    top = max((position["y"] for position in layout.values()), default=0.0) + 1.8
    lines = [
        _HEADERS["tikz"],
        r"\documentclass[tikz,border=6pt]{standalone}",
        r"\usetikzlibrary{arrows.meta,backgrounds,fit,positioning}",
        r"\begin{document}",
        r"\begin{tikzpicture}[>=Stealth, font=\small, every node/.style={align=center}]",
    ]
    if graph["title"]:
        lines.append(
            rf"\node[font=\bfseries] at (0.00, {top:.2f}) {{{_tikz_escape(graph['title'])}}};"
        )
    for node in nodes:
        position = layout[node["id"]]
        lines.append(
            r"\node[draw, rounded corners, fill=white] "
            rf"({names[node['id']]}) at ({position['x']:.2f}, {position['y']:.2f}) "
            rf"{{{_tikz_escape(node['label'])}}};"
        )
    if clusters:
        lines.append(r"\begin{scope}[on background layer]")
        for index, cluster in enumerate(clusters):
            if not cluster["nodes"]:
                continue
            fit = "".join(f"({names[node_id]})" for node_id in cluster["nodes"])
            lines.append(
                rf"\node[draw, dashed, rounded corners, fill=blue!4, inner sep=14pt, "
                rf"fit={{{fit}}}, "
                rf"label={{[font=\bfseries\small]above:{_tikz_escape(cluster['label'])}}}] "
                rf"(cluster{index + 1}) {{}};"
            )
        lines.append(r"\end{scope}")
    for edge in edges:
        options = ["->"]
        if edge["style"] == "dashed":
            options.append("dashed")
        elif edge["style"] == "bold":
            options.append("line width=1.1pt")
        elif edge["style"] == "invisible":
            options.append("draw=none")
        arrow = rf"\draw[{', '.join(options)}] ({names[edge['source']]}) -- "
        if edge["label"]:
            arrow += rf"node[midway, above, font=\scriptsize] {{{_tikz_escape(edge['label'])}}} "
        arrow += f"({names[edge['target']]});"
        lines.append(arrow)
    lines.extend([r"\end{tikzpicture}", r"\end{document}"])
    return "\n".join(lines).rstrip() + "\n"


def _build_matplotlib(graph: dict[str, Any], layout: dict[str, dict[str, float]]) -> str:
    nodes = graph["nodes"]
    edges = graph["edges"]
    clusters = graph["clusters"]
    names = _safe_names(nodes)
    node_payload = [
        {
            "name": names[node["id"]],
            "label": node["label"],
            "group": node["group"],
            "x": round(layout[node["id"]]["x"], 3),
            "y": round(layout[node["id"]]["y"], 3),
        }
        for node in nodes
    ]
    edge_payload = [
        {
            "source": names[edge["source"]],
            "target": names[edge["target"]],
            "label": edge["label"],
            "style": edge["style"],
        }
        for edge in edges
    ]
    cluster_payload = [
        {
            "id": f"c{index + 1}",
            "label": cluster["label"],
            "nodes": [names[node_id] for node_id in cluster["nodes"]],
        }
        for index, cluster in enumerate(clusters)
    ]
    lines = [
        _HEADERS["matplotlib"],
        "import matplotlib.pyplot as plt",
        "from matplotlib.patches import FancyBboxPatch",
        "",
        f"TITLE = {graph['title']!r}",
        f"NODES = {node_payload!r}",
        f"EDGES = {edge_payload!r}",
        f"CLUSTERS = {cluster_payload!r}",
        "",
        "",
        "def main(output=\"diagram.png\"):",
        "    fig, ax = plt.subplots(figsize=(8, 4.5))",
        "    for cluster in CLUSTERS:",
        "        members = [n for n in NODES if n[\"name\"] in cluster[\"nodes\"]]",
        "        if not members:",
        "            continue",
        "        xs = [n[\"x\"] for n in members]",
        "        ys = [n[\"y\"] for n in members]",
        "        box = FancyBboxPatch(",
        "            (min(xs) - 0.9, min(ys) - 0.6),",
        "            (max(xs) - min(xs)) + 1.8,",
        "            (max(ys) - min(ys)) + 1.2,",
        "            boxstyle=\"round,pad=0.02\",",
        "            fill=False,",
        "            linestyle=\"--\",",
        "            edgecolor=\"#4c72b0\",",
        "        )",
        "        ax.add_patch(box)",
        "        ax.text(min(xs) - 0.85, max(ys) + 0.45, cluster[\"label\"], fontsize=8, weight=\"bold\")",
        "    for edge in EDGES:",
        "        source = next(n for n in NODES if n[\"name\"] == edge[\"source\"])",
        "        target = next(n for n in NODES if n[\"name\"] == edge[\"target\"])",
        "        ax.annotate(",
        "            \"\",",
        "            xy=(target[\"x\"], target[\"y\"]),",
        "            xytext=(source[\"x\"], source[\"y\"]),",
        "            arrowprops={\"arrowstyle\": \"->\", \"color\": \"#333333\"},",
        "        )",
        "        if edge[\"label\"]:",
        "            ax.text(",
        "                (source[\"x\"] + target[\"x\"]) / 2,",
        "                (source[\"y\"] + target[\"y\"]) / 2 + 0.18,",
        "                edge[\"label\"],",
        "                fontsize=7,",
        "                ha=\"center\",",
        "            )",
        "    for node in NODES:",
        "        ax.text(node[\"x\"], node[\"y\"], node[\"label\"], ha=\"center\", va=\"center\", fontsize=8,",
        "                bbox={\"boxstyle\": \"round,pad=0.35\", \"fc\": \"white\", \"ec\": \"#333333\"})",
        "    ax.set_title(TITLE, fontsize=10)",
        "    ax.set_xlim(-2, 15)",
        "    ax.set_ylim(-8, 4)",
        "    ax.axis(\"off\")",
        "    fig.tight_layout()",
        "    fig.savefig(output, dpi=160, bbox_inches=\"tight\")",
        "",
        "",
        "if __name__ == \"__main__\":",
        "    main()",
    ]
    return "\n".join(lines) + "\n"


_BUILDERS = {
    "mermaid": _build_mermaid,
    "graphviz": _build_graphviz,
    "tikz": _build_tikz,
    "matplotlib": _build_matplotlib,
}


def diagram(spec: dict[str, Any], kind: str = "mermaid") -> dict[str, Any]:
    """把结构化图描述渲染成确定性脚本文本（不执行外部工具）。"""
    kind_key = str(kind or "").strip().lower()
    kind_key = _KIND_ALIASES.get(kind_key, kind_key)
    if kind_key not in SUPPORTED_KINDS:
        raise ValidationError(
            f"不支持的图形类型: {kind!r}；可选 {list(SUPPORTED_KINDS)}"
        )
    graph = _normalize_spec(spec)
    if not graph["nodes"]:
        raise ValidationError("spec.nodes 不能为空：图形至少需要一个节点")
    if not graph["edges"]:
        raise ValidationError("spec.edges 不能为空：图形至少需要一条边")

    layout = _layered_layout(graph["nodes"], graph["edges"])
    script = _BUILDERS[kind_key](graph, layout)
    extension = _EXTENSIONS[kind_key]
    filename = f"diagram-{short_id(script, 12)}.{extension}"
    notes = [
        f"已生成 {kind_key} 脚本文本（未执行渲染，本机无 tikz/graphviz 编译器）",
        f"{len(graph['nodes'])} 个节点 / {len(graph['edges'])} 条边 / {len(graph['clusters'])} 个分组",
        "布局由确定性拓扑分层给出；同一 spec 的脚本字节级一致",
    ]
    return {
        "kind": kind_key,
        "script": script,
        "filename": filename,
        "notes": notes,
        "nodes": len(graph["nodes"]),
        "edges": len(graph["edges"]),
    }
